import{c as a,Q as s,j as n,m as r}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"Harness-Bench: Measuring Harness Effects across Models in Realistic Agent Workflows","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.27922","title":"Harness-Bench: Measuring Harness Effects across Models in Realistic Agent Workflows","archived_date":"2026-07-18T00:00:00.000Z","arxiv_id":2605.27922,"authors":["Yilun Yao","Xinyu Tan","Chao-Hsuan Liu","Yaoming Li","Zhengyang Wang","Wenhan Yu","Zhewen Tan","Yuxuan Tian","Guangxiang Zhao","Lin Sun","Xiangzheng Zhang","Tong Yang"],"pdf_path":"pdfs/2605.27922.pdf","published_date":"2026-05-27T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-27-harness-bench-measuring-harness-effects-2605-27922.md","filePath":"research/papers/2026-05-27-harness-bench-measuring-harness-effects-2605-27922.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-05-27-harness-bench-measuring-harness-effects-2605-27922.md"};function o(i,e,c,l,h,g){return s(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="harness-bench-measuring-harness-effects-across-models-in-realistic-agent-workflows" tabindex="-1">Harness-Bench: Measuring Harness Effects across Models in Realistic Agent Workflows <a class="header-anchor" href="#harness-bench-measuring-harness-effects-across-models-in-realistic-agent-workflows" aria-label="Permalink to &quot;Harness-Bench: Measuring Harness Effects across Models in Realistic Agent Workflows&quot;">​</a></h1><p><strong>Authors</strong>: Yilun Yao, Xinyu Tan, Chao-Hsuan Liu, Yaoming Li, Zhengyang Wang, Wenhan Yu, Zhewen Tan, Yuxuan Tian, Guangxiang Zhao, Lin Sun, Xiangzheng Zhang, Tong Yang <strong>Published</strong>: May 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2605.27922" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.27922</a><strong>arXiv ID</strong>: 2605.27922 <strong>Categories</strong>: Computer Science &gt; Artificial Intelligence (cs.AI) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2605.27922" target="_blank" rel="noreferrer">research/papers/pdfs/2605.27922.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>LLM agents are increasingly deployed as executable systems that use tools, modify workspaces, and produce concrete artifacts. In such workflows, performance depends not only on the base model, but also on the harness: the system layer that manages context, tools, state, constraints, permissions, tracing, and recovery. However, existing benchmarks typically abstract away execution, compare complete agent systems, or hold the harness fixed, making execution-layer variation difficult to study. The authors introduce a diagnostic benchmark for evaluating configuration-level harness effects in realistic agent workflows. The benchmark evaluates representative harness configurations across multiple model backends under shared task environments, budgets, and evaluation protocols, while preserving each harness&#39;s native execution behavior. It contains 106 sandboxed offline tasks constructed from practical agent-use patterns and manually reviewed for realism, solvability, oracle-checkability, and integrity. Analysis of 5,194 execution trajectories reveals substantial variation in completion, process quality, efficiency, and failure behavior across model-harness pairings. Results suggest that agent capability should be reported at the model-harness configuration level rather than attributed to the base model alone.</p><hr><h2 id="core-thesis" tabindex="-1">Core Thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core Thesis&quot;">​</a></h2><ul><li>指出主流 agent benchmark 的方法論缺口：不是抽象掉執行層、就是整包比較完整 agent 系統、或固定 harness 不變，導致「執行層變異」（harness 本身造成的效能差異）難以獨立研究。</li><li>建立診斷型 benchmark：106 個沙盒化離線任務（涵蓋真實可解性、oracle 可驗證性、完整性審核），在共享任務環境/預算/評測協定下，交叉評測代表性 harness 組態 × 多個模型後端，同時保留各 harness 原生執行行為。</li><li>分析 5,194 條執行軌跡，發現同一模型搭配不同 harness 在完成率、過程品質、效率、失敗行為上有顯著差異。</li><li>結論：agent 能力應以「model-harness 組態」層級回報，而非單獨歸因於底層模型——呼應同批次多篇論文（Interplay of Harness Design、Belief Divergence）共同指向的方法論轉向。</li><li><strong>Workspace 關聯</strong>：為 <code>.claude/refs/model-profiles.md</code> 的檔位選型提供實證依據——模型升降級評估不應只看模型本身 benchmark，還須考慮 harness 組態（本 workspace 的 hooks/skills/agents 層）本身對效能的貢獻，換模型世代時規則需重審的立場再獲支持。</li></ul>',8)])])}const f=a(t,[["render",o]]);export{d as __pageData,f as default};
